// Census (printed with the jit_ccalls probe, latched at reset so the emitted
// counters and the C ones always describe the same blocks). Costs nothing
// when off: emitted counters are simply not generated.
enum
{
	ARMC_SLICE, ARMC_DISPATCH, ARMC_DISPATCH_C, ARMC_FIQ,
	ARMC_COMPILE, ARMC_LINK_C, ARMC_DYN, ARMC_IC_SITE, ARMC_IC_MISS,
	ARMC_IC_PATCH, ARMC_IC_DEMOTE, ARMC_RD_SLOW, ARMC_WR_SLOW, ARMC_LDM,
	ARMC_STM, ARMC_BLK_INLINE, ARMC_OTHER,
	// dynamic exits by shape (e_dyn_exit)
	ARMC_DYN_MOV, ARMC_DYN_SUB, ARMC_DYN_DP_OTHER, ARMC_DYN_LDR_IMM,
	ARMC_DYN_LDR_LIT, ARMC_DYN_LDR_REG, ARMC_DYN_LDM, ARMC_DYN_SWI,
	ARMC_COUNT
};
extern "C" int g_jit_ccalls_preset;   // dc/sh4/rec_v2/shil.cpp
static bool   s_census;
static u32    s_cnt[ARMC_COUNT];
#define ARMC(i) do { if (s_census) s_cnt[i]++; } while (0)

// Census wall time inside the C side, to set against arm:% on the stats line.
// Only the outermost timer on the stack counts (jit_link_c -> jit_dispatch_c).
enum { ARMT_DISPATCH, ARMT_RD, ARMT_WR, ARMT_BLOCK, ARMT_OTHER, ARMT_COUNT };
static u64    s_tcost[ARMT_COUNT];
static bool   s_timing;
struct CensusTimer
{
	u32 k; u64 t0; bool on;
	explicit CensusTimer(u32 kind) : k(kind), t0(0), on(s_census && !s_timing)
	{
		if (on) { s_timing = true; t0 = gettime(); }
	}
	~CensusTimer()
	{
		if (on) { s_tcost[k] += gettime() - t0; s_timing = false; }
	}
};

// Block-table entries written since the last flush. The table is 2 MB and the
// self-test alone resets ~45 times, so a flush clears only this range, unless
// the cached interpreter may have filled the table since (full clear then).
static u32    s_dirty_lo = 0xFFFFFFFF;
static u32    s_dirty_hi;
static bool   s_table_foreign = true;

static bool   s_setup_done;
static bool   s_setup_ok;
static bool   s_active;
static bool   s_failed;             // self-test failed: never latch the JIT again
static bool   s_selftest_started;
static bool   s_announced;
static u32    s_blocks;
static u32    s_flushes;

// reg[15] materialized in THIS instruction (value known at compile time)?
static bool   s_pc15_known;
static u32    s_pc15_val;

// ── Small emit helpers ───────────────────────────────────────────────────────
static inline bool in_s16(s32 v) { return v >= -32768 && v <= 32767; }

static inline void e_rlwinm(u32 a, u32 s, u32 sh, u32 mb, u32 me)
{
	ppc_rlwinmx(a, s, sh & 31, mb, me, 0);
}

// Level 5 ("lean"): an instruction's ticks are summed at compile time and
// charged once, with `addic.`, at its end (or before its exit branch). The
// resulting CR0 is the next instruction's budget test, so each instruction
// after the first needs only `ble` instead of `cmpwi / ble / addi`. Same
// budget at every exit point as the per-instruction form, so same timing.
static bool s_fold;                 // arm7_jit >= 5
static u32  s_ticks;                // ticks of the current instruction not yet charged
static bool s_cr0_budget;           // CR0 holds the sign of the budget right now

// N/Z forwarding (level 5): the previous instruction was an unconditional N/Z
// producer whose result is still in this PPC register (0 = none), so an
// EQ/NE/MI/PL test compares it instead of reloading the flag byte just stored.
static u32  s_nz_fwd_next;
static bool s_nz_in_r7;             // this instruction set N/Z from r7

static inline void e_ticks(u32 n)
{
	if (s_fold)
		s_ticks += n;
	else
		ppc_addi(R_BUD, R_BUD, (u32)(-(s32)n));
}

// Charge the pending ticks (level 5). set_cr0: leave CR0 = budget sign for the
// next instruction's `ble`; exits don't need it (the next block tests itself).
static void e_charge(bool set_cr0)
{
	if (!s_fold)
		return;
	if (s_ticks)
		ppc_addic(R_BUD, R_BUD, (u32)(-(s32)s_ticks), set_cr0 ? 1 : 0);
	else if (set_cr0)
		ppc_cmpi(0, R_BUD, 0, 0);
	s_ticks = 0;
}

static void e_load_byte(u32 dst, void* p)
{
	s32 d = (s32)((u8*)p - (u8*)&N_FLAG);
	if (in_s16(d))
		ppc_lbz(dst, R_FLG, (u32)d);
	else
	{
		u32 lo = ppc_addr_high(dst, p);
		ppc_lbz(dst, dst, lo);
	}
}

static void e_store_byte(u32 src, void* p)
{
	s32 d = (s32)((u8*)p - (u8*)&N_FLAG);
	if (in_s16(d))
		ppc_stb(src, R_FLG, (u32)d);
	else
	{
		u32 lo = ppc_addr_high(11, p);
		ppc_stb(src, 11, lo);
	}
}

static void e_load_reg(u32 dst, u32 r)
{
	if (r == 15 && s_pc15_known)
		ppc_li(dst, s_pc15_val);
	else
		ppc_lwz(dst, R_REG, r * 4);
}

static void e_store_reg(u32 src, u32 r)
{
	ppc_stw(src, R_REG, r * 4);
	if (r == 15)
		s_pc15_known = false;
}

// The cached interpreter's SET_PC_READ / "_pcr" shift uop: write reg[15] to
// memory (later instructions may read it back) and remember the constant.
static void e_set_pc15(u32 val)
{
	ppc_li(12, val);
	ppc_stw(12, R_REG, 15 * 4);
	s_pc15_known = true;
	s_pc15_val = val;
}

static void e_call(void* f)
{
	ppc_call(f);
	s_pc15_known = false;   // conservative: helpers may write reg[15]
}

// Census counter bump (r11/r12, flags untouched). Emitted only with the census on.
static const u32 COUNT_WORDS = 4;
static void e_count(u32 idx)
{
	if (!s_census)
		return;
	u32* start = emit_ptr;
	u32 lo = ppc_addr_high(12, &s_cnt[idx]);
	ppc_lwz(11, 12, lo);
	ppc_addi(11, 11, 1);
	ppc_stw(11, 12, lo);
	verify(emit_ptr - start == (s32)COUNT_WORDS);
}

static u32* e_bc_placeholder(u32 bo, u32 bi)
{
	u32* site = emit_ptr;
	ppc_bcx(bo, bi, 0, 0, 0);
	return site;
}

static void patch_bc(u32* site, u32* target)
{
	s32 d = (s32)((u8*)target - (u8*)site);
	verify(in_s16(d));
	*site |= (u32)d & 0xFFFC;
}

static void e_bc_to(u32 bo, u32 bi, u32* target)
{
	s32 d = (s32)((u8*)target - (u8*)emit_ptr);
	verify(in_s16(d));
	ppc_bcx(bo, bi, (u32)(d >> 2), 0, 0);
}

// N and Z from the result in r7 (r9 temp).
static void e_flags_nz(u32 res)
{
	e_rlwinm(9, res, 1, 31, 31);
	e_store_byte(9, &N_FLAG);
	ppc_cntlzwx(9, res, 0);
	e_rlwinm(9, 9, 27, 31, 31);
	e_store_byte(9, &Z_FLAG);
	s_nz_in_r7 = (res == 7);
}

// C from XER[CA] (must run right after the flag-producing add/sub).
static void e_flag_c_from_ca()
{
	ppc_li(9, 0);
	ppc_addzex(9, 9, 0, 0);
	e_store_byte(9, &C_FLAG);
}

// XER[CA] = C_FLAG, for adde/subfe.
static void e_ca_from_c()
{
	e_load_byte(8, &C_FLAG);
	ppc_addic(8, 8, (u32)-1, 0);
}

